// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// HYPOTHESIS-1: Fine-grained input-length thresholds (32/128/256) better separate cache-beneficial from non-beneficial requests than previous coarser bins
	// MECHANISM-1: 32-token boundary catches minimal prefixes (cache_warmup short inputs); 128-token catches medium prefixes; 256+ gets full cache benefit
	// EXPECT-1: cache_warmup_e2e_ms < 4100

	// HYPOTHESIS-2: Dual-phase overload penalty (linear + quadratic) prevents load_spikes hot-spotting while preserving cache routing for balanced loads
	// MECHANISM-2: Linear penalty handles mild imbalance gracefully; quadratic penalty above avg+3 threshold aggressively redirects from severely overloaded instances
	// EXPECT-2: load_spikes_e2e_ms < 3250

