	// MECHANISM-3: Multi-turn sessions with long prefixes have expensive KV state; 2.5x affinity boost ensures they stay on cache-warm instances
	// EXPECT-3: multiturn_e2e_ms < 165

	inputLen := len(req.InputTokens)

	// Adaptive weight computation with fine-grained input-length thresholds
	w0 := ws.weights[0] // prefix-affinity
	w1 := ws.weights[1] // load-balance
	if len(ws.weights) >= 2 {
		// Fine-grained input length stratification
		if inputLen < 32 {
			// Minimal prefix: pure load-balancing
			w0, w1 = 0.05, 0.95
		} else if inputLen < 128 {
			// Small prefix: slight cache benefit
			w0, w1 = 0.25, 0.75
		} else if inputLen < 256 {
			// Medium prefix: moderate cache benefit
			w0, w1 = 0.45, 0.55
		} else {
			// Long prefix: strong cache benefit
			w0, w1 = 0.65, 0.35
		}

