		if req.SLOClass == "realtime" {
			w0 *= 0.55
			w1 *= 1.35
		} else if req.SLOClass == "batch" {
			w0 *= 1.15
			w1 *= 0.90
		}

		// Session-aware boosting for long multi-turn prefixes
		if req.SessionID != "" && inputLen >= 256 {
			w0 *= 2.5
			w1 *= 0.5
		}

		// Normalize
		total := w0 + w1
		if total > 0 {
