	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	// HYPOTHESIS-1: Block-aligned input thresholds (64 tokens) with stronger load-balance bias for short inputs reduces cache_warmup imbalance
	// MECHANISM-1: Inputs <=64 tokens have at most 1-2 cache blocks; prefix-affinity score differences are minimal but can still cause imbalance
	// EXPECT-1: cache_warmup_e2e_ms < 4800
	// HYPOTHESIS-2: Restoring multiplicative overload penalty at 1.3x avgLoad (from best program) prevents load_spikes hot-spotting
	// MECHANISM-2: Program 1 achieved -4799 with 1.3x threshold; the current 2.0x threshold is too lenient and allows hot-spots to form
	// EXPECT-2: load_spikes_e2e_ms < 3400
	// HYPOTHESIS-3: Moderate session affinity boost (1.4x vs 2.0x) preserves multiturn while avoiding over-concentration
	// MECHANISM-3: Excessive boosting can create secondary hot-spots on session-heavy instances; gentler boost maintains cache benefit with better balance
	// EXPECT-3: avg_e2e_ms < 2700

	// Compute per-scorer raw scores separately
	rawScores := make([]map[string]float64, len(ws.scorers))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		rawScores[i] = make(map[string]float64, len(snapshots))
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			rawScores[i][snap.ID] = s
		}
	}

	// Determine adaptive weights based on request characteristics
	inputLen := len(req.InputTokens)
	adaptiveWeights := make([]float64, len(ws.weights))
	copy(adaptiveWeights, ws.weights)

