	// We adjust the balance based on context
	if len(adaptiveWeights) >= 2 {
		prefixW := adaptiveWeights[0] // prefix-affinity weight
		loadW := adaptiveWeights[1]   // load-balance weight

		// Block-aligned thresholds: 64 tokens ≈ 2-4 cache blocks (assuming 16-32 token blocks)
		// This aligns with actual cache granularity rather than arbitrary cutoffs
		if inputLen <= 64 {
			// Very short: minimal cache blocks, strongly favor load-balance
			prefixW = 0.05
			loadW = 0.95
		} else if inputLen <= 256 {
			// Medium: transition zone with moderate cache benefit
			prefixW = 0.50
			loadW = 0.50
		} else {
			// Long prefixes: substantial cache state worth preserving
			prefixW = 0.70
			loadW = 0.30
		}

